from pysat.solvers import Glucose3
import itertools

def solve():
    n = 18
    # We want to find if there is a graph with n=18, girth >= 8, edges >= 29
    # Let's just use a SAT solver with lazy clause generation for cycles.

    # Variables: e_{i,j} for i < j
    edges = []
    idx = 1
    var_map = {}
    for i in range(n):
        for j in range(i+1, n):
            var_map[(i, j)] = idx
            edges.append((i, j))
            idx += 1

    solver = Glucose3()

    # At least 29 edges
    # We can use a cardinality constraint. Since 29 is small, we can use sequential counter or PySAT's CardEnc
    from pysat.card import CardEnc, EncType
    cnf = CardEnc.atleast(lits=[var_map[e] for e in edges], bound=29, encoding=EncType.seqcounter, top_id=idx)
    for clause in cnf.clauses:
        solver.add_clause(clause)

    # Lazy generation
    def find_cycle(adj):
        # BFS to find shortest cycle
        # Return the edges of the cycle if length <= 7
        for start in range(n):
            visited = {start: -1}
            queue = [(start, 0, -1)] # node, depth, parent
            while queue:
                curr, depth, parent = queue.pop(0)
                if depth >= 4: # cycle length up to 7 means depth up to 3. Wait, depth 3 + depth 4 = 7.
                    continue
                for neighbor in adj[curr]:
                    if neighbor == parent:
                        continue
                    if neighbor in visited:
                        # Cycle found
                        cycle_len = depth + visited[neighbor] + 1
                        if cycle_len <= 7:
                            # Reconstruct cycle
                            # This is a bit tricky with just BFS. Let's do a simple shortest path between all edges.
                            pass
        return None

    # Better cycle finder
    import collections
    def get_short_cycle(adj):
        for i in range(n):
            dist = {i: 0}
            parent = {i: -1}
            q = collections.deque([i])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if v == parent[u]:
                        continue
                    if v in dist:
                        if dist[u] + dist[v] + 1 <= 7:
                            # Found a short cycle!
                            # Reconstruct it
                            path1 = []
                            curr = u
                            while curr != -1:
                                path1.append(curr)
                                curr = parent[curr]
                            path2 = []
                            curr = v
                            while curr != -1:
                                path2.append(curr)
                                curr = parent[curr]

                            # Find lowest common ancestor
                            path1.reverse()
                            path2.reverse()
                            lca_idx = 0
                            while lca_idx < len(path1) and lca_idx < len(path2) and path1[lca_idx] == path2[lca_idx]:
                                lca_idx += 1
                            lca_idx -= 1

                            cycle_nodes = path1[lca_idx:] + path2[lca_idx+1:][::-1]
                            cycle_edges = []
                            for k in range(len(cycle_nodes)):
                                u1 = cycle_nodes[k]
                                v1 = cycle_nodes[(k+1)%len(cycle_nodes)]
                                cycle_edges.append((min(u1, v1), max(u1, v1)))
                            return cycle_edges
                    else:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        q.append(v)
        return None

    iters = 0
    while solver.solve():
        iters += 1
        model = solver.get_model()
        adj = {i: [] for i in range(n)}
        active_edges = []
        for e in edges:
            if model[var_map[e] - 1] > 0:
                adj[e[0]].append(e[1])
                adj[e[1]].append(e[0])
                active_edges.append(e)

        cycle = get_short_cycle(adj)
        if cycle:
            # Add clause to forbid this cycle
            clause = [-var_map[e] for e in cycle]
            solver.add_clause(clause)
        else:
            print(f"Found graph with {len(active_edges)} edges after {iters} iterations!")
            return True

        if iters % 100 == 0:
            print(f"Iter {iters}")

    print("UNSAT")
    return False

