import random

def get_girth(adj, N):
    # Find the shortest cycle using BFS
    min_cycle = float('inf')
    for start in range(N):
        dist = {start: 0}
        parent = {start: -1}
        q = [start]
        while q:
            u = q.pop(0)
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    # Cycle found
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
                        if min_cycle <= 7:
                            return min_cycle
    return min_cycle

def local_search():
    N = 21
    E = 27

    # Start with a random graph with E edges
    edges = set()
    while len(edges) < E:
        u = random.randint(0, N-1)
        v = random.randint(0, N-1)
        if u != v:
            if u > v: u, v = v, u
            edges.add((u, v))

    edges = list(edges)

    def make_adj(edges):
        adj = {i: [] for i in range(N)}
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        return adj

    best_girth = 0

    for step in range(100000):
        adj = make_adj(edges)
        g = get_girth(adj, N)

        if g >= 8:
            print("Found!")
            print(edges)
            return edges

        if g > best_girth:
            best_girth = g
            print(f"Step {step}: girth {g}")

        # Mutate
        idx = random.randint(0, E-1)
        old_edge = edges[idx]

        # Try to find a new edge that doesn't create small cycles
        # We can just pick a random non-edge
        u = random.randint(0, N-1)
        v = random.randint(0, N-1)
        if u > v: u, v = v, u
        if u != v and (u, v) not in edges:
