def moore_bound(d, g):
    if g % 2 == 1:
        k = (g - 1) // 2
        return 1 + d * sum((d - 1)**i for i in range(k))
    else:
        k = g // 2
        return 2 * sum((d - 1)**i for i in range(k))

print(moore_bound(4, 8))

def check_girth(n, generators):
    adj = {i: set() for i in range(n)}
    for i in range(n):
        for g in generators:
            adj[i].add((i + g) % n)
            adj[i].add((i - g) % n)

    # BFS to find shortest cycle
    girth = n + 1
    for i in range(n):
        dist = {i: 0}
        q = [(i, -1)]
        while q:
            u, p = q.pop(0)
            for v in adj[u]:
                if v == p: continue
                if v in dist:
                    girth = min(girth, dist[u] + dist[v] + 1)
                else:
                    dist[v] = dist[u] + 1
                    q.append((v, u))
    return girth

