            while q:
                u, p, d = q.popleft()
                if d == 3:
                    continue
                for v in adj[u]:
                    if v == p:
                        continue
                    if v in visited:
                        cycle_len = d + 1 + visited[v]
                        if cycle_len <= 6:
                            cycle_edges = []
                            curr = u
                            while curr != start:
                                cycle_edges.append((curr, parent[curr]))
                                curr = parent[curr]
                            curr = v
                            while curr != start:
                                cycle_edges.append((curr, parent[curr]))
                                curr = parent[curr]
                            cycle_edges.append((u, v))
                            return cycle_edges
                    else:
                        visited[v] = d + 1
                        parent[v] = u
                        q.append((v, u, d + 1))
        return None

    iters = 0
    while solver.solve():
        iters += 1
        model = solver.get_model()
        model_set = set(model)
        edges_list = []
        for i in range(N):
            for j in range(i+1, N):
                if edge_var(i, j) in model_set:
                    edges_list.append((i, j))

        cycle = find_short_cycle(edges_list)
        if cycle is None:
            print(f"Found solution after {iters} iterations!")
            print(edges_list)
            return edges_list

        clause = []
        for u, v in cycle:
            clause.append(-edge_var(u, v))
        solver.add_clause(clause)

        if iters % 100 == 0:
            print(f"Iteration {iters}, added clause of length {len(clause)}")

    print("UNSAT")
    return None

solve()

